po = {"PO-4500001": {"item": "금형 A", "qty": 10, "price": 1_200_000}}
gr = {"PO-4500001": 8}
inv = {"PO-4500001": (10, 1_200_000)}
for po_no, p in po.items():
    got, (iq, ip) = gr.get(po_no, 0), inv[po_no]
    issues = []
    if iq > got: issues.append(f"송장 수량 {iq} > 입고 {got}")
    if ip != p["price"]: issues.append(f"단가 {ip:,} != 발주 {p['price']:,}")
    print(po_no, "지급 보류:" if issues else "지급 가능", "; ".join(issues))
# PO-4500001 지급 보류: 송장 수량 10 > 입고 8
